/**
 * Official brand glyphs and colors for catalog entries, from simple-icons
 * (CC0). Generated by generate-brand-icons.mjs; do not edit by hand. The
 * colors are the vendors' own brand colors, which is why they are literal
 * values and not theme tokens. Entries absent here fall back to the vendor
 * logo, then the generic sprite icon.
 */
type BrandIcon = {
    path: string;
    /** The brand color, the tile's fill. */
    color: string;
    /** Black or white, whichever contrasts with the fill. */
    glyph: string;
};
/** The brand glyph for a catalog entry id, if the brand exists in simple-icons. */
export declare const brandIconFor: (id: string) => BrandIcon | undefined;
export {};
